import {artworkMarkup} from './artwork-markup.js';
import {initPrinciples} from './atlas-principles.js?v=2';
import {initFrequency} from './atlas-frequency.js';
const $=id=>document.getElementById(id);
const escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const memory=new Map();
function read(key,fallback){if(memory.has(key))return memory.get(key);try{const value=JSON.parse(localStorage.getItem(key));if(value!==null){memory.set(key,value);return value;}}catch{}return fallback;}
function write(key,value){memory.set(key,value);try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{return false;}}
let toastTimer;
function notify(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,3700);}
function download(name,content,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
const keys=['atlas-saved-places','atlas-saved-routes','atlas-observations','atlas-principle-notes','atlas-frequency-draft'];
let locations=[],routes=[],knowledge={},selectedId='notre-dame',layer='All layers',map,markerGroup,routeLine,userMarker,userPosition,activeRouteId=null,frequency,principles,atlasData;
const layers=['All layers','Architecture','Symbolism','Alchemy','Graffiti','Music','Astronomy'];
const neighbourhoods={'notre-dame':'Île de la Cité Latin Quarter','sainte-chapelle':'Île de la Cité','saint-sulpice':'Saint Germain des Prés','flamel-house':'Le Marais Nicolas Flamel','la-place':'Les Halles Châtelet','mur-oberkampf':'Oberkampf Belleville Ménilmontant','pere-lachaise':'Ménilmontant Gambetta','republique':'République Marianne','abbesses':'Montmartre Hector Guimard','centquatre':'La Chapelle Curial Riquet','philharmonie':'La Villette Jean Nouvel','shakespeare-company':'Latin Quarter George Whitman'};
function arrayStore(key){const a=read(key,[]);return Array.isArray(a)?a.filter(x=>typeof x==='string'):[];}
function objectStore(key){const x=read(key,{});return x&&typeof x==='object'&&!Array.isArray(x)?x:{};}
function savedCount(){const count=arrayStore('atlas-saved-places').length+arrayStore('atlas-saved-routes').length;$('saved-count').textContent=count;$('notebook-open').setAttribute('aria-label',`Open field notebook, ${count} saved discoveries and routes`);}
const bookmarkIcon=saved=>`<svg viewBox="0 0 24 28" aria-hidden="true"><path d="M5 3h14v22l-7-5-7 5Z" fill="${saved?'currentColor':'none'}"/></svg>`;
function toggleSaved(kind,id){const key=kind==='route'?'atlas-saved-routes':'atlas-saved-places';const set=new Set(arrayStore(key));const removed=set.has(id);removed?set.delete(id):set.add(id);const okay=write(key,[...set]);savedCount();notify(okay?(removed?'Removed from your notebook.':'Saved in your field notebook.'):'Kept for this visit. Browser storage is unavailable.');document.querySelectorAll(`[data-save-${kind}="${id}"]`).forEach(button=>{button.setAttribute('aria-pressed',String(!removed));button.innerHTML=bookmarkIcon(!removed);button.setAttribute('aria-label',`${!removed?'Unsave':'Save'} ${kind==='route'?'route':'discovery'}`);});}
function saveButton(kind,id,name){const saved=arrayStore(kind==='route'?'atlas-saved-routes':'atlas-saved-places').includes(id);return `<button class="save-icon" data-save-${kind}="${escape(id)}" aria-label="${saved?'Unsave':'Save'} ${escape(name)}" aria-pressed="${saved}">${bookmarkIcon(saved)}</button>`;}
const conceptDiagram=(id)=>`<svg class="diagram" viewBox="0 0 400 210" role="img" aria-label="Contemporary geometric study, not a documentary photograph"><circle cx="200" cy="105" r="78"/><circle cx="200" cy="105" r="56"/><path d="M200 22 275 148H125ZM200 188 125 63h150ZM122 105h156M200 27v156"/><circle cx="200" cy="105" r="8"/><path d="M35 185H365M35 25V185M365 25V185M25 165H375"/><text x="200" y="202" text-anchor="middle" fill="currentColor" stroke="none" font-size="8" letter-spacing="3">CAISIK / VISUAL STUDY</text></svg>`;
function lensStudy(p){
 const intro=`<strong>LOOK / ${escape(p.categories.join(' · '))}</strong><p>${escape(p.observe)}</p>`;
 if(p.id!=='notre-dame')return intro+`<p><b>Documented detail:</b> ${escape(p.symbols)}</p><p>This is an observation guide. The photo's archival caption and source determine what it documents.</p>`;
 return intro+`<svg class="lens-facade" viewBox="0 0 600 320" role="img" aria-label="Schematic west facade of Notre-Dame: two towers, central rose window, three portals. Simplified architectural illustration, not a survey."><path d="M70 285V40H180V285M420 285V40H530V285M180 285V130H420V285M60 40H190M410 40H540M60 285H540M180 130H420M70 175H530M70 215H530"/><path d="M90 115V60H115V115M135 115V60H160V115M440 115V60H465V115M485 115V60H510V115M92 285V252Q125 201 158 252V285M254 285V245Q300 187 346 245V285M442 285V252Q475 201 508 252V285"/><circle cx="300" cy="169" r="31"/><circle cx="300" cy="169" r="24"/><path d="M269 169H331M300 138V200M278 147 322 191M278 191 322 147"/><g class="lens-dot"><circle cx="300" cy="169" r="42"/><circle cx="126" cy="90" r="43"/><path d="M246 293H354"/></g><text x="348" y="157">01</text><text x="175" y="76">02</text><text x="362" y="277">03</text></svg><p class="privacy-line">Schematic architectural illustration · proportions simplified; no secret alignment implied.</p><div class="lens-detail-buttons"><button class="small-button" data-lens-detail="0">01 / ROSE</button><button class="small-button" data-lens-detail="1">02 / TOWERS</button><button class="small-button" data-lens-detail="2">03 / PORTALS</button></div><p id="symbol-lens-caption" class="lens-detail-caption">01 / The central rose combines circular geometry with Christian imagery. The philosophical reading of many perspectives is a contemporary analogy.</p>`;
}

function imageBlock(location,full=false){const photo=location.photo;if(!photo)return `<div class="${full?'profile-visual':'place-image'}">${conceptDiagram(location.id)}<span class="image-credit">Creative study · <a href="${escape(location.sources[0].url)}" target="_blank" rel="noopener">View venue imagery ↗</a></span></div>`;return `<div class="${full?'profile-visual':'place-image'}"><img src="${escape(photo.localUrl||photo.remoteUrl)}" alt="${escape(location.name+' — '+photo.note)}" loading="lazy" data-place-photo="${escape(location.id)}" referrerpolicy="no-referrer"><a class="image-credit" href="${escape(photo.sourcePage)}" target="_blank" rel="noopener">${escape(photo.author)} · ${escape(photo.license)}${photo.note.toLowerCase().includes('archiv')?' · ARCHIVE':''} ↗</a></div>`;}
function imageFallbacks(scope){scope.querySelectorAll('img[data-place-photo]').forEach(img=>img.addEventListener('error',()=>{const parent=img.parentElement;img.remove();parent.insertAdjacentHTML('afterbegin',conceptDiagram('fallback'));const credit=parent.querySelector('.image-credit');if(credit)credit.textContent='Photo unavailable here · open credited source ↗';},{once:true}));}
function current(){return locations.find(x=>x.id===selectedId)||locations[0];}
function renderPreview(){const p=current();if(!p)return;$('place-preview').innerHTML=`<div class="preview-heading"><p class="section-index">${String(locations.indexOf(p)+1).padStart(2,'0')} / ${escape(p.categories.slice(0,2).join(' & '))}</p>${saveButton('place',p.id,p.name)}</div><h3>${escape(p.name)}</h3><p class="place-address">⌖ ${escape(p.address)}</p>${imageBlock(p)}<p class="evidence-label">HISTORICAL EVIDENCE</p><p class="preview-history">${escape(p.history)}</p><div class="preview-interpretation"><p class="evidence-label">ARTISTIC INTERPRETATION</p>${escape(p.interpretation.replace(/^CAISIK reading: /,''))}</div><div class="preview-actions"><button class="button" data-open-place="${escape(p.id)}">OPEN DISCOVERY <span>→</span></button><button class="small-button" data-inspire="${escape(p.id)}">MAKE A VERSE ↗</button></div>`;imageFallbacks($('place-preview'));}
function selectPlace(id,pan=false){if(!locations.some(x=>x.id===id))return;selectedId=id;renderPreview();$('place-list').querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.selectPlace===id)));if(map){markerGroup.eachLayer(marker=>{const el=marker.getElement?.();if(el)el.classList.toggle('active',marker.options.placeId===id);});if(pan){const p=current();map.panTo([p.lat,p.lng]);}}}
function normalized(value){return value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();}
function filtered(){const term=normalized($('place-search').value.trim());const period=$('period-filter').value;const access=$('access-filter').value;return locations.filter(p=>(layer==='All layers'||p.categories.includes(layer))&&(!term||normalized([p.name,p.address,p.history,p.symbols,p.interpretation,p.categories.join(' '),neighbourhoods[p.id]].join(' ')).includes(term))&&(!period||p.period===period)&&(!access||(access==='verified'?p.accessVerified:p.outdoorViewing)));}
function renderPlaces(){let visible=filtered();if(userPosition)visible.sort((a,b)=>distance(a,userPosition)-distance(b,userPosition));$('result-count').textContent=`${visible.length} / ${locations.length} DISCOVERIES`;$('place-list').innerHTML=visible.length?visible.map(p=>`<button type="button" data-select-place="${escape(p.id)}" aria-pressed="${p.id===selectedId}"><span>${String(locations.indexOf(p)+1).padStart(2,'0')}</span>${escape(p.name)}${userPosition?`<small>~${distance(p,userPosition).toFixed(1)} km</small>`:''}</button>`).join(''):'<p class="no-results">No discoveries match this combination. Try another layer or clear your search.</p>';if(map){markerGroup.clearLayers();visible.forEach(p=>{const index=locations.indexOf(p);const marker=L.marker([p.lat,p.lng],{placeId:p.id,keyboard:true,title:p.name,alt:p.name,icon:L.divIcon({className:`atlas-pin ${p.id===selectedId?'active':''}`,html:`<span class="pin-disc">${String(index+1).padStart(2,'0')}</span>`,iconSize:[30,30],iconAnchor:[15,15]})});marker.bindTooltip(p.name,{direction:'top',offset:[0,-15]});marker.on('click',()=>selectPlace(p.id));marker.addTo(markerGroup);});}if(visible.length){if(!visible.some(p=>p.id===selectedId))selectPlace(visible[0].id);else renderPreview();}else if(!visible.length){$('place-preview').innerHTML='<h3>No matching discoveries.</h3><p class="muted">Change the filters to reveal another layer of Paris.</p><button class="button" data-reset-filters>RESET FILTERS →</button>';}}
function resetFilters(){layer='All layers';$('place-search').value='';$('period-filter').value='';$('access-filter').value='';renderFilterButtons();renderPlaces();renderPreview();}
function renderFilterButtons(){$('layer-filters').innerHTML=layers.map(x=>`<button data-layer="${x}" aria-pressed="${x===layer}">${x}</button>`).join('');}
function setupMap(){if(!window.L){$('map-failure').hidden=false;return;}try{map=L.map('city-map',{scrollWheelZoom:false,zoomControl:true}).setView([48.8685,2.357],12);markerGroup=L.layerGroup().addTo(map);let tilesOkay=false,errorCount=0;const tiles=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a>',maxZoom:19});tiles.on('tileload',()=>{tilesOkay=true;$('map-failure').hidden=true;});tiles.on('tileerror',()=>{if(!tilesOkay&&++errorCount>=4)$('map-failure').hidden=false;});tiles.addTo(map);L.control.scale({imperial:false,position:'bottomleft'}).addTo(map);new ResizeObserver(()=>map.invalidateSize()).observe($('city-map'));}catch{$('map-failure').hidden=false;}}
function distance(p,u){const rad=Math.PI/180,dl=(p.lat-u.lat)*rad,dg=(p.lng-u.lng)*rad,a=Math.sin(dl/2)**2+Math.cos(p.lat*rad)*Math.cos(u.lat*rad)*Math.sin(dg/2)**2;return 6371*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a));}
function renderRoutes(){$('routes').innerHTML=routes.map((r,i)=>`<article class="route"><span class="route-num">0${i+1} / ${r.stops.length} STOPS</span><h4>${escape(r.title)}</h4><p>${escape(r.description)}</p><div class="route-actions"><button data-route="${r.id}" aria-pressed="${r.id===activeRouteId}">TRACE THE ROUTE →</button>${saveButton('route',r.id,r.title)}</div></article>`).join('');}
function directionsUrl(route){const stops=route.stops.map(id=>locations.find(p=>p.id===id));const params=new URLSearchParams({api:'1',origin:stops[0].address,destination:stops.at(-1).address,travelmode:'walking'});if(stops.length>2)params.set('waypoints',stops.slice(1,-1).map(p=>p.address).join('|'));return `https://www.google.com/maps/dir/?${params}`;}
function showRoute(id){const r=routes.find(x=>x.id===id);if(!r)return;activeRouteId=id;resetFilters();if(routeLine&&map)map.removeLayer(routeLine);if(map){const points=r.stops.map(id=>locations.find(p=>p.id===id)).map(p=>[p.lat,p.lng]);routeLine=L.polyline(points,{color:'#ffd600',weight:1.5,dashArray:'5,9',interactive:false}).addTo(map);map.fitBounds(routeLine.getBounds(),{padding:[40,40],maxZoom:14});}selectPlace(r.stops[0]);$('active-route').hidden=false;$('active-route').innerHTML=`<h4>${escape(r.title)}</h4><div class="route-stops">${r.stops.map((id,i)=>`<button data-route-stop="${id}">${i+1}. ${escape(locations.find(p=>p.id===id).name)}</button>${i<r.stops.length-1?'<span aria-hidden="true">→</span>':''}`).join('')}</div><p>The dashed line shows the stop sequence, not a walkable path. Live directions determine the walking route. Venue hours and temporary restrictions apply.</p><a class="button" href="${escape(directionsUrl(r))}" target="_blank" rel="noopener">OPEN WALKING DIRECTIONS ↗</a> <button class="small-button" id="close-route">CLOSE ROUTE</button>`;renderRoutes();}
function stopNarration(){if('speechSynthesis'in window)window.speechSynthesis.cancel();document.querySelectorAll('[data-narrate]').forEach(b=>b.textContent='LISTEN / DEVICE VOICE');}
function openProfile(id){selectPlace(id);stopNarration();const p=current();const nearby=locations.filter(x=>x.id!==p.id).sort((a,b)=>distance(a,p)-distance(b,p)).slice(0,3);const obs=objectStore('atlas-observations')[id]||'';$('profile-content').innerHTML=`<p class="section-index">PARIS / DISCOVERY ${String(locations.indexOf(p)+1).padStart(2,'0')}</p><h2 id="profile-title">${escape(p.name)}</h2><p class="profile-title-address">${escape(p.address)} · ${escape(p.period)}</p>${imageBlock(p,true)}${p.photo?`<p class="privacy-line">${escape(p.photo.note)} · <a href="${escape(p.photo.sourcePage)}" target="_blank" rel="noopener">Image & credit</a> · <a href="${escape(p.photo.licenseUrl)}" target="_blank" rel="noopener">${escape(p.photo.license)}</a></p>`:''}<div class="lens-toggle"><button class="small-button" data-profile-lens aria-expanded="false">◎ OPEN SYMBOL LENS</button><button class="small-button" data-narrate>LISTEN / DEVICE VOICE</button><button class="small-button" data-stop-narration>STOP VOICE</button></div><div id="symbol-lens" class="lens-annotation" hidden>${lensStudy(p)}</div><div class="profile-columns"><div><section class="profile-block"><h3>Historical evidence</h3><p>${escape(p.history)}</p><h3>Documented symbols</h3><p>${escape(p.symbols)}</p></section><section class="profile-block profile-interpretation"><h3>Artistic interpretation</h3><p>${escape(p.interpretation)}</p><h3>Ask yourself</h3><p>${escape(p.reflection)}</p></section><section class="profile-block"><h3>Street to sound</h3><p>${escape(p.challenge)}</p><button class="button" data-profile-inspire="${id}">TAKE THIS TO THE LAB →</button></section></div><div><section class="profile-block"><h3>Access & the public boundary</h3><p>${escape(p.access)}</p><h3>Accessibility</h3><p>${escape(p.accessibility)}</p><p class="muted">Map position: ${escape(p.coordinateStatus)}. Check the official venue before your visit.</p><a class="text-link" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(p.name+' '+p.address)}" target="_blank" rel="noopener">NAVIGATE TO THE ADDRESS ↗</a></section><section class="profile-block"><h3>Sources & visitor information</h3><ul class="profile-source-list">${p.sources.map(s=>`<li><a href="${escape(s.url)}" target="_blank" rel="noopener">${escape(s.title)} ↗</a></li>`).join('')}</ul><p class="privacy-line">Checked 21 October 2026. Conditions can change.</p></section></div></div><section class="profile-block profile-observation"><h3>Leave a note for yourself</h3><label for="place-observation">What did you see? What did you interpret?</label><textarea id="place-observation" maxlength="3000" placeholder="Separate the detail from the story you gave it…">${escape(obs)}</textarea><button class="small-button" data-save-observation="${id}">SAVE MY OBSERVATION ↗</button> ${saveButton('place',id,p.name)}<p class="privacy-line">Stored in this browser, never submitted. Export your field notebook to keep a copy.</p></section><section class="profile-block"><h3>Nearby threads</h3><div class="nearby-links">${nearby.map(n=>`<button data-open-place="${n.id}">${escape(n.name)} ↗</button>`).join('')}</div></section>`;imageFallbacks($('profile-content'));const dialog=$('profile-dialog');if(!dialog.open)dialog.showModal();dialog.scrollTop=0;}
function inspire(id){const p=locations.find(x=>x.id===id);if(!p)return;frequency?.setInspiration(p);$('profile-dialog').close();$('frequency').scrollIntoView({behavior:document.documentElement.dataset.motion==='off'?'instant':'smooth'});notify(`Creative starting point: ${p.name}`);}
const artThemes=[
{title:'AS ABOVE / SO BELOW',scene:'as-above',width:1312,height:1199,asset:'072',description:'Mirrored architectural geometry in crisp black-and-yellow ink.',prompt:'Find an echo between a skyline and a small detail. Draw the difference as carefully as the resemblance.'},
{title:'TRANSMUTE',scene:'transmute',width:1536,height:1024,image:'/assets/atlas/transmute-approved.webp',download:'/assets/atlas/transmute-approved.png',description:'Approved black-and-yellow graphic-novel wildstyle. Thought becomes letter architecture.',prompt:'Take one word you use against yourself. Redraw it as a direction you can act on.'},
{title:'THE MAP IS NOT THE TERRITORY',scene:'map-territory',width:1536,height:1024,asset:'089',description:'Frame the City — an original study of the city held inside a frame.',prompt:'Draw your route from memory, then compare it with the geographic map. What did memory enlarge?'},
{title:'KNOW THYSELF',scene:'know-thyself',width:1536,height:1024,asset:'005',description:'Interlocking letters and a question that stays open.',prompt:'Write three observations about yourself. Separate what happened from the label you added.'},
{title:'SHADOW WORK',scene:'shadow-work',width:1254,height:1254,asset:'033',description:'Unmask — an illustrated portrait curated for this theme.',prompt:'Give a hidden feeling a fictional character. Let it speak four lines without making it your whole identity.'},
{title:'OMERTÀ WITH THE EGO',scene:'omerta-ego',width:1600,height:800,asset:'039',description:'Inward Eyes — silence, attention and a gaze turned inward.',prompt:'Write a scene without defending yourself or blaming somebody else. Describe only what you could observe.'},
{title:'THE CITY REMEMBERS',scene:'city-remembers',width:1254,height:1254,asset:'049',description:'Rooftop Frequency — industrial forms assembled into a city memory.',prompt:'Choose one alteration on a street. Sketch what remains and leave space for what you cannot know.'},
{title:'FREQUENCY OF THE UNDERGROUND',scene:'vibration',width:1254,height:1254,asset:'023',description:'Vibration — a tuning fork held inside an orbital composition.',prompt:'Choose three environmental sounds. Turn each one into a repeated phrase.'}];
const artSceneMarkup=a=>artworkMarkup({id:a.scene,poster:a.image||`/assets/masterworks-v2/${a.asset}.webp`,width:a.width,height:a.height});
function renderArt(){$('art-gallery').innerHTML=artThemes.map((a,i)=>`<button class="art-piece" data-art="${i}" aria-label="Open ${escape(a.title)}">${artSceneMarkup(a)}<div class="art-caption"><div><h3>${escape(a.title)}</h3><small>0${i+1} / ORIGINAL CAISIK COMPOSITION</small></div><span>↗</span></div></button>`).join('');}
function openArt(index){const a=artThemes[index];if(!a)return;$('art-content').innerHTML=`<p class="section-index">THE LIVING WALL / 0${index+1}</p><h2 id="art-title">${escape(a.title)}</h2><div class="art-motion-scope art-dialog-scene"><button class="art-dialog-trigger" type="button" style="--art-ratio:${a.width}/${a.height}" aria-label="Awaken ${escape(a.title)} artwork">${artSceneMarkup(a)}</button><div class="art-dialog-motion"><span>MOVE CLOSER. WAKE THE DETAIL.</span><button type="button" class="small-button" data-art-replay>REPLAY ARTWORK ↻</button></div></div><p>${escape(a.description)}</p><p class="evidence-label">YOUR CREATIVE RESPONSE</p><p>${escape(a.prompt)}</p><div class="dialog-actions"><a class="button" href="${a.download||`/assets/masterworks-v2/${a.asset}.webp`}" download>DOWNLOAD ARTWORK ↓</a><button class="small-button" data-art-inspire="${index}">WRITE A RESPONSE ↗</button></div>`;$('art-dialog').showModal();}
function renderNotebook(){const ps=arrayStore('atlas-saved-places').map(id=>locations.find(p=>p.id===id)).filter(Boolean),rs=arrayStore('atlas-saved-routes').map(id=>routes.find(r=>r.id===id)).filter(Boolean),notes=objectStore('atlas-observations'),pn=objectStore('atlas-principle-notes');$('notebook-content').innerHTML=`<div class="notebook-group"><h3>Saved discoveries / ${ps.length}</h3>${ps.length?ps.map(p=>`<div class="notebook-item"><button data-notebook-place="${p.id}">${escape(p.name)} →</button><button data-remove-place="${p.id}" aria-label="Remove ${escape(p.name)}">REMOVE</button></div>`).join(''):'<p class="empty-state">Save a location with its bookmark to start your archive.</p>'}</div><div class="notebook-group"><h3>Saved routes / ${rs.length}</h3>${rs.map(r=>`<div class="notebook-item"><button data-notebook-route="${r.id}">${escape(r.title)} →</button><button data-remove-route="${r.id}">REMOVE</button></div>`).join('')||'<p class="empty-state">Your saved routes will appear here.</p>'}</div><div class="notebook-group"><h3>Street observations</h3>${Object.entries(notes).filter(([id,n])=>locations.some(p=>p.id===id)&&typeof n==='string').map(([id,n])=>`<p class="evidence-label">${escape(locations.find(p=>p.id===id).name)}</p><p class="notebook-note">${escape(n)}</p>`).join('')||'<p class="empty-state">Open a discovery and save what you noticed.</p>'}</div><div class="notebook-group"><h3>Inner observations</h3>${Object.entries(pn).filter(([id,n])=>knowledge.principles?.some(p=>p.id===id)&&typeof n?.text==='string').map(([id,n])=>`<p class="evidence-label">${escape(knowledge.principles.find(p=>p.id===id).name)} / ${n.unlocked?'DEEPER QUESTION OPEN':'IN PROGRESS'}</p><p class="notebook-note">${escape(n.text)}</p>`).join('')||'<p class="empty-state">The seven-principle studio gives you a place to reflect.</p>'}</div>`;}
function renderSources(){const photoSources=locations.filter(p=>p.photo).map(p=>`<div class="source-group"><h3>${escape(p.name)} / image</h3><p>${escape(p.photo.credit)}<br>${escape(p.photo.note)}</p><a href="${escape(p.photo.sourcePage)}" target="_blank" rel="noopener">Source image ↗</a><a href="${escape(p.photo.licenseUrl)}" target="_blank" rel="noopener">${escape(p.photo.license)} ↗</a></div>`).join('');$('source-register').innerHTML=`<p class="muted">Research checked 21 October 2026. Sources support the historical and access fields; creative readings are original editorial interpretations. Archival photographs do not establish current appearance or access.</p>${locations.map(p=>`<div class="source-group"><h3>${escape(p.name)}</h3>${p.sources.map(s=>`<a href="${escape(s.url)}" target="_blank" rel="noopener">${escape(s.title)} ↗</a>`).join('')}</div>`).join('')}<div class="source-group"><h3>Philosophy & practice</h3>${knowledge.sources.map(s=>`<a href="${escape(s.url)}" target="_blank" rel="noopener">${escape(s.title)} ↗</a>`).join('')}</div><h3>Image credits</h3>${photoSources}<p class="privacy-line">Hero collage and graffiti are AI-assisted original CAISIK artwork in the approved black-and-yellow graphic-novel direction; the hero is a conceptual composition, not documentary evidence. Map tiles and geographic data: OpenStreetMap contributors. Leaflet is BSD-2-Clause; bundled font licenses are included with the source.</p>`;}
function setupEvents(){
 $('menu-toggle').onclick=()=>{const expanded=$('menu-toggle').getAttribute('aria-expanded')==='true';$('menu-toggle').setAttribute('aria-expanded',String(!expanded));$('main-nav').classList.toggle('open',!expanded);};
 $('main-nav').onclick=()=>{$('main-nav').classList.remove('open');$('menu-toggle').setAttribute('aria-expanded','false');};
 $('place-search').oninput=()=>renderPlaces();$('period-filter').onchange=()=>renderPlaces();$('access-filter').onchange=()=>renderPlaces();
 $('locate').onclick=()=>{if(!navigator.geolocation){$('geo-status').textContent='Location is unavailable. Search by place or neighbourhood instead.';return;}$('geo-status').textContent='Waiting for your location permission…';$('locate').disabled=true;navigator.geolocation.getCurrentPosition(position=>{userPosition={lat:position.coords.latitude,lng:position.coords.longitude};$('locate').disabled=false;$('geo-status').textContent='Discoveries sorted by approximate straight-line distance. Your location is kept only for this visit.';if(map){if(userMarker)map.removeLayer(userMarker);userMarker=L.marker([userPosition.lat,userPosition.lng],{icon:L.divIcon({className:'user-location',iconSize:[12,12]})}).addTo(map);if(distance(locations[0],userPosition)<40)map.panTo([userPosition.lat,userPosition.lng]);}renderPlaces();},error=>{$('locate').disabled=false;$('geo-status').textContent=error.code===1?'Location permission declined. Search the atlas by neighbourhood instead.':'Your location could not be found. Search the atlas by neighbourhood instead.';},{enableHighAccuracy:false,timeout:12000,maximumAge:60000});};
 $('notebook-open').onclick=()=>{renderNotebook();$('clear-confirm').hidden=true;$('notebook-dialog').showModal();};
 $('notebook-export').onclick=()=>{const exported={project:'CAISIK UNDERGROUND ALCHEMY',exportedAt:new Date().toISOString(),formatVersion:1,...Object.fromEntries(keys.map(k=>[k,read(k,k.endsWith('places')||k.endsWith('routes')?[]:{})]))};download('caisik-field-notebook.json',JSON.stringify(exported,null,2));notify('Notebook exported. Keep the file somewhere safe.');};
 $('notebook-clear').onclick=()=>$('clear-confirm').hidden=false;$('cancel-clear').onclick=()=>$('clear-confirm').hidden=true;$('confirm-clear').onclick=()=>{keys.forEach(k=>{memory.delete(k);try{localStorage.removeItem(k);}catch{}});location.reload();};
 $('sources-open').onclick=()=>{renderSources();$('sources-dialog').showModal();};
 const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;let motion=read('atlas-motion',reduced?'off':'on');document.documentElement.dataset.motion=motion;$('motion-toggle').setAttribute('aria-pressed',String(motion==='off'));$('motion-toggle').textContent=motion==='off'?'RESUME MOTION':'PAUSE MOTION';$('motion-toggle').onclick=()=>{motion=motion==='off'?'on':'off';document.documentElement.dataset.motion=motion;write('atlas-motion',motion);$('motion-toggle').setAttribute('aria-pressed',String(motion==='off'));$('motion-toggle').textContent=motion==='off'?'RESUME MOTION':'PAUSE MOTION';};
 document.querySelectorAll('dialog').forEach(d=>{d.querySelector('[data-close]').onclick=()=>d.close();d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});});$('profile-dialog').addEventListener('close',stopNarration);
 document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;const d=b.dataset;
  if(d.layer){layer=d.layer;renderFilterButtons();renderPlaces();}
  if(d.door){layer=d.door;renderFilterButtons();renderPlaces();}
  if(d.resetFilters!==undefined)resetFilters();
  if(d.selectPlace)selectPlace(d.selectPlace,true);
  if(d.savePlace)toggleSaved('place',d.savePlace);
  if(d.saveRoute)toggleSaved('route',d.saveRoute);
  if(d.openPlace)openProfile(d.openPlace);
  if(d.inspire)inspire(d.inspire);
  if(d.profileInspire)inspire(d.profileInspire);
  if(d.route)showRoute(d.route);
  if(d.routeStop)selectPlace(d.routeStop,true);
  if(b.id==='close-route'){if(routeLine&&map)map.removeLayer(routeLine);activeRouteId=null;$('active-route').hidden=true;renderRoutes();}
  if(d.art!==undefined)openArt(Number(d.art));
  if(d.artInspire!==undefined){const a=artThemes[Number(d.artInspire)];frequency?.setInspiration({name:a.title,challenge:a.prompt});$('art-dialog').close();$('frequency').scrollIntoView();}
  if(d.saveObservation){const text=$('place-observation').value.trim();if(!text){notify('Write an observation first.');return;}const notes=objectStore('atlas-observations');notes[d.saveObservation]=text;notify(write('atlas-observations',notes)?'Observation saved in your notebook.':'Kept for this visit. Browser storage is unavailable.');}
  if(d.profileLens!==undefined){const el=$('symbol-lens');el.hidden=!el.hidden;b.setAttribute('aria-expanded',String(!el.hidden));b.textContent=el.hidden?'◎ OPEN SYMBOL LENS':'◎ CLOSE SYMBOL LENS';}
  if(d.lensDetail!==undefined){const captions=['01 / The central rose combines circular geometry with Christian imagery. The philosophical reading of many perspectives is a contemporary analogy.','02 / The paired towers frame the western facade. Their vertical divisions provide an observable architectural rhythm, not evidence of a hidden doctrine.','03 / The three western portals have documented Christian programmes: the Virgin, the Last Judgment and Saint Anne. Read the narrative before inventing a meaning.'];$('symbol-lens-caption').textContent=captions[Number(d.lensDetail)]||captions[0];}
  if(d.narrate!==undefined){if(!('speechSynthesis'in window)){notify('Device narration is unavailable. Read the profile text instead.');return;}const voice=window.speechSynthesis.getVoices().find(v=>v.localService&&/^en/i.test(v.lang));if(!voice){notify('No local English voice is available on this device. The full text is below.');return;}stopNarration();const p=current(),speech=new SpeechSynthesisUtterance(`${p.name}. Historical evidence. ${p.history} Documented symbols. ${p.symbols} Artistic interpretation. ${p.interpretation} Look for this. ${p.observe}`);speech.voice=voice;speech.rate=.9;speech.onend=()=>b.textContent='LISTEN / DEVICE VOICE';window.speechSynthesis.speak(speech);b.textContent='READING / DEVICE VOICE';}
  if(d.stopNarration!==undefined)stopNarration();
  if(d.notebookPlace){$('notebook-dialog').close();openProfile(d.notebookPlace);}
  if(d.notebookRoute){$('notebook-dialog').close();showRoute(d.notebookRoute);$('hidden-city').scrollIntoView();}
  if(d.removePlace){toggleSaved('place',d.removePlace);renderNotebook();}
  if(d.removeRoute){toggleSaved('route',d.removeRoute);renderNotebook();}
 });
 document.addEventListener('visibilitychange',()=>{if(document.hidden)stopNarration();});window.addEventListener('pagehide',stopNarration);
}
async function init(){try{const [a,p]=await Promise.all([fetch('/locations-data.json').then(r=>{if(!r.ok)throw Error();return r.json();}),fetch('/principles-data.json').then(r=>{if(!r.ok)throw Error();return r.json();})]);atlasData=a;locations=a.locations;routes=a.routes;knowledge=p;setupEvents();renderFilterButtons();[...new Set(locations.map(p=>p.period))].forEach(period=>{const option=document.createElement('option');option.value=period;option.textContent=period;$('period-filter').append(option);});setupMap();renderPlaces();renderPreview();renderRoutes();renderArt();savedCount();principles=initPrinciples($('principles'),{data:knowledge,read,write,notify});frequency=initFrequency($('frequency'),{data:knowledge,read,write,notify,getLocation:current});const qr=location.pathname.match(/^\/q\/([^/]+)/)?.[1];if(qr){const ids={'generation':'gender','as-above':'correspondence','so-below':'correspondence','shadow-work':'mentalism','underground':'vibration','transmute':'cause-effect'};principles?.select(ids[qr]||qr);$('principles').scrollIntoView({behavior:'instant'});}else if(['#principles','#living-wall'].includes(location.hash)){$(location.hash.slice(1)).scrollIntoView({behavior:'instant'});}if('speechSynthesis'in window)window.speechSynthesis.getVoices();}catch(error){console.error('Atlas initialization failed',error);$('place-preview').innerHTML='<h3>The atlas could not load.</h3><p>Reload the page to try again. Official visitor links remain available in the research section.</p>';$('principles').textContent='The learning data could not load. Reload to try again.';$('frequency').textContent='The laboratory could not load. Reload to try again.';}}
init();
